using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class OperationalAudit {static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("B5_Operational_Detail");Physics.SyncTransforms();var meshes=group.GetComponentsInChildren<MeshFilter>().Select(m=>m.sharedMesh).Distinct().ToArray();int deg=0;long tris=0;foreach(var m in meshes){var vs=m.vertices;var ts=m.triangles;tris+=ts.Length/3;for(int i=0;i<ts.Length;i+=3)if(Vector3.Cross(vs[ts[i+1]]-vs[ts[i]],vs[ts[i+2]]-vs[ts[i]]).sqrMagnitude<1e-22f)deg++;}
 var missing=group.GetComponentsInChildren<Renderer>().Where(r=>r.sharedMaterials.Any(m=>!m)).Select(r=>PathOf(r.transform)).ToArray();var overlaps=new List<object>();var cols=group.GetComponentsInChildren<Collider>().Where(c=>c.enabled).ToArray();for(int i=0;i<cols.Length;i++)for(int j=i+1;j<cols.Length;j++){var a=cols[i];var b=cols[j];if(!a.bounds.Intersects(b.bounds))continue;if(a is MeshCollider&&b is MeshCollider)continue;Vector3 dir;float depth;if(Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out dir,out depth)&&depth>.025f)overlaps.Add(new{a=PathOf(a.transform),b=PathOf(b.transform),depth});}
 var result=new{scene=s.path,uniqueMeshes=meshes.Length,triangles=tris,degenerate=deg,missingMaterials=missing,overlaps,placements=group.Cast<Transform>().SelectMany(t=>t.Cast<Transform>().Where(x=>x.GetComponentInChildren<MeshFilter>()).Select(x=>new{room=t.name,name=x.name,asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(x.gameObject),position=V(x.localPosition),yaw=x.localEulerAngles.y})),hierarchy=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=PathOf(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=PathOf(l.transform),position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.enabled,l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()})};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_OperationalDetail/audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{meshes=meshes.Length,triangles=tris,degenerate=deg,missing=missing.Length,overlaps};}}
